package com.quicknotes.app;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;
public class Reminders extends BroadcastReceiver {
 static PendingIntent alarm(Context c,String id,String title){return PendingIntent.getBroadcast(c,id.hashCode(),new Intent(c,Reminders.class).setAction("reminder:"+id).putExtra("id",id).putExtra("title",title),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,JSONObject d)throws Exception{AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray items=d.getJSONArray("items");for(int n=0;n<items.length();n++){JSONObject i=items.getJSONObject(n);PendingIntent pi=alarm(c,i.getString("id"),i.optString("title"));am.cancel(pi);long due=i.optLong("due");if(!i.optBoolean("done")&&!i.optBoolean("deleted")&&due>System.currentTimeMillis())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}}
 public void onReceive(Context c,Intent intent){try{JSONObject d;try(InputStream in=new FileInputStream(new File(c.getFilesDir(),"data.json"))){d=new JSONObject(new String(MainActivity.bytes(in,MainActivity.MAX_BUNDLE),"UTF-8"));}if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){schedule(c,d);return;}String id=intent.getStringExtra("id");JSONArray a=d.getJSONArray("items");JSONObject item=null;for(int n=0;n<a.length();n++)if(a.getJSONObject(n).getString("id").equals(id))item=a.getJSONObject(n);if(item==null||item.optBoolean("done")||item.optBoolean("deleted"))return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("reminders","Reminder alerts",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(id.hashCode(),new Notification.Builder(c,"reminders").setSmallIcon(com.quicknotes.app.R.drawable.ic_notification).setContentTitle(item.optString("title")).setContentText(item.optString("notes","Reminder due")).setContentIntent(open).setAutoCancel(true).build());}catch(Exception ignored){}}
}
